-- 안전재고 계산 (Supabase SQL 편집기에서 실행해 적용함) · 안전재고 = 지난 1년 하루 최대 판매량, 일자별 기록 없으면 0 · 최대 = 안전재고 + 24개월 월평균 × 정한 개월
create or replace function public.safety_recalc_core() returns integer language plpgsql security definer set search_path to 'public' as $function$ declare st public.safety_settings; n int; m0 date := date_trunc('month', current_date)::date; begin select * into st from public.safety_settings where id = 1; create temp table _mon on commit drop as select item_code, mon, qty as q, item_name as nm, spec as sp from public.sales_monthly where mon >= (m0 - interval '24 months') and mon < m0; insert into _mon select l.item_code, date_trunc('month', l.doc_date)::date, sum(l.qty), max(l.item_name), max(l.spec) from public.ec_lines l where l.kind = '판매' and l.item_code is not null and l.doc_date >= (m0 - interval '24 months') and l.doc_date < m0 and not exists (select 1 from public.sales_monthly s where s.item_code = l.item_code and s.mon = date_trunc('month', l.doc_date)::date) group by 1, 2; create temp table _day on commit drop as select t.item_code, max(t.q) as mx from (select l.item_code, l.doc_date, sum(l.qty) as q from public.ec_lines l where l.kind = '판매' and l.item_code is not null and l.doc_date > (current_date - interval '1 year') and l.doc_date <= current_date group by 1, 2) t group by 1; with agg as ( select item_code, max(nm) as nm, max(sp) as sp, count(*) filter (where q <> 0) as months_sold, sum(q) as tot, sum(q*q) as tot2 from _mon group by 1), calc as ( select item_code, nm, sp, months_sold, tot/24.0 as avg_m, sqrt(greatest((tot2 - tot*tot/24.0)/23.0, 0)) as sd from agg where tot > 0) insert into public.safety_stock(item_code, item_name, spec, avg_month, sd_month, months_sold, safety, max_qty, calc_at) select item_code, c.nm, c.sp, round(c.avg_m, 1), round(c.sd, 1), c.months_sold, case when c.months_sold < st.min_months then 0 else ceil(greatest(coalesce(d.mx, 0), 0)) end, ceil(greatest(coalesce(d.mx, 0), 0) + c.avg_m * st.max_months), now() from calc c left join _day d using (item_code) on conflict (item_code) do update set item_name = excluded.item_name, spec = excluded.spec, avg_month = excluded.avg_month, sd_month = excluded.sd_month, months_sold = excluded.months_sold, safety = excluded.safety, max_qty = excluded.max_qty, calc_at = excluded.calc_at; get diagnostics n = row_count; delete from public.safety_stock s where s.manual_safety is null and s.manual_max is null and not exists (select 1 from _mon m where m.item_code = s.item_code and m.q > 0); update public.safety_settings set updated_by = coalesce(my_username(), updated_by), updated_at = now() where id = 1; return n; end $function$;
